// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SSHCommand) predicate.SSHCommand {
	return predicate.SSHCommand(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SSHCommand) predicate.SSHCommand {
	return predicate.SSHCommand(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SSHCommand) predicate.SSHCommand {
	return predicate.SSHCommand(sql.NotPredicates(p))
}
